values ('bbbb0004-0000-4000-8000-000000000015', 'en', null, 'World Geography', 'A first tour of how the planet is put together — landforms and climate, where people live and move, and how regions differ in culture and wealth. Structure adapted from OpenStax World Regional Geography (CC BY 4.0).', null, 'foundations', 21, true, 'science', '{}')
