insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000015', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The theory that Earth''s outer shell is broken into slow-moving pieces is called…","options":["continental drift only","plate tectonics","erosion","the water cycle"],"answer":1,"explanation":"Plate tectonics explains most large landforms — see ''Physical geography: a restless planet''."},{"prompt":"The band of hot, wet climate found near the equator supports which biome?","options":["tundra","desert","tropical rainforest","taiga"],"answer":2,"explanation":"Equatorial heat plus heavy rain gives rainforest — see ''Climate and biomes''."},{"prompt":"As of the mid-2020s, the world''s most populous country is…","options":["China","India","the United States","Indonesia"],"answer":1,"explanation":"India passed China around 2023 — see ''People on the move''."},{"prompt":"A reason that pushes people to LEAVE a place is called a…","options":["pull factor","push factor","birth rate","biome"],"answer":1,"explanation":"Push factors drive people out; pull factors attract them — see ''People on the move''."},{"prompt":"Roughly what share of the world''s people now live in cities?","options":["about 10%","about 30%","more than half","nearly all"],"answer":2,"explanation":"The world crossed 50% urban around 2007 — see ''People on the move''."},{"prompt":"The world''s single largest language family by number of speakers'' native tongues is…","options":["Indo-European","only English","Latin","Esperanto"],"answer":0,"explanation":"Indo-European stretches from Europe to South Asia — see ''Culture, language, and belief''."},{"prompt":"A common single measure that combines income, education, and life expectancy is the…","options":["GDP","Human Development Index (HDI)","birth rate","latitude"],"answer":1,"explanation":"HDI is broader than income alone — see ''Wealth, work, and development''."},{"prompt":"Meeting today''s needs without harming the ability of the future to meet its own is called…","options":["urbanization","sustainability","migration","erosion"],"answer":1,"explanation":"That is the classic definition of sustainable development — see ''Wealth, work, and development''."}]}'::jsonb, null, 10),
  (2, 'Physical geography: a restless planet', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how plate tectonics builds mountains, oceans, volcanoes, and earthquakes. Warm-up: from the diagnostic, what is the name for Earth''s broken outer shell of moving pieces?"},{"heading":"The idea","text":"Earth''s rigid outer layer is cracked into about a dozen large *tectonic plates* that drift on the hot, slowly flowing rock beneath them. Where plates meet, the boundary type decides the landform. At *convergent* boundaries plates push together and crumple crust upward or force one plate to dive under another. At *divergent* boundaries plates pull apart and new crust rises to fill the gap. At *transform* boundaries plates grind sideways past each other. Most of the planet''s earthquakes and volcanoes cluster along these seams."},{"heading":"Worked example","text":"The Himalayas, home to Mount Everest, are still rising because the Indian plate is colliding into the Eurasian plate — a convergent boundary. Around the edges of the Pacific, plates dive beneath their neighbors, feeding a chain of volcanoes and quakes nicknamed the ''Ring of Fire''. Iceland, by contrast, sits on a divergent boundary in the Atlantic and is literally splitting apart."},{"heading":"Your turn","text":"Name the boundary type for each: (1) two plates colliding to raise the Himalayas, (2) the Mid-Atlantic Ridge where seafloor spreads, (3) California''s San Andreas Fault where plates slide past, (4) an ocean plate diving under South America to build the Andes. Answers: (1) convergent, (2) divergent, (3) transform, (4) convergent."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking mountains form overnight — they rise over millions of years. Mistake: assuming continents ''float'' on water (they ride on solid but slowly flowing rock). Exit: (a) Which boundary type builds most tall mountain ranges? (b) What loops the Pacific with volcanoes and earthquakes? Answers: convergent; the Ring of Fire."}]}'::jsonb, 'Convergent = plates collide; divergent = plates spread; transform = plates slide past.', 12),
  (3, 'Climate and biomes', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why climate changes with latitude and altitude, and match major climates to their biomes. Warm-up: what biome do you expect right on the equator, and why?"},{"heading":"The idea","text":"*Climate* is the long-run pattern of temperature and precipitation, not a single day''s *weather*. The Sun strikes the equator most directly, so the tropics stay warm; sunlight hits the poles at a low angle, so they stay cold. Rising warm air near the equator dumps rain, while air sinking near 30° north and south dries the land — which is why many of the world''s great deserts, like the Sahara, sit in those belts. A *biome* is a large community of life shaped by climate: tropical rainforest, savanna, desert, temperate forest, grassland, boreal forest (taiga), and tundra. Climbing a tall mountain mimics traveling toward the pole, because temperature also drops with altitude."},{"heading":"Worked example","text":"Trace a line from the equator toward the North Pole through Africa and Eurasia: rainforest near the equator gives way to savanna, then the Sahara desert near 30°N, then Mediterranean and temperate forest, then vast taiga across Russia, and finally treeless tundra near the Arctic. Each shift tracks falling heat and changing rainfall."},{"heading":"Your turn","text":"Match climate cue to biome: (1) hot and wet all year near the equator, (2) very dry near 30° latitude, (3) freezing, treeless ground near the poles, (4) cold snowy winters with evergreen forests across northern Canada and Russia. Options: desert / tundra / tropical rainforest / taiga. Answers: (1) tropical rainforest, (2) desert, (3) tundra, (4) taiga."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing weather (today''s rain) with climate (the decades-long average). Mistake: assuming deserts are only hot — many, like the Gobi, are cold. Exit: (a) Why are many big deserts found near 30° latitude? (b) Name the treeless polar biome. Answers: sinking dry air there; tundra."}]}'::jsonb, 'Weather is today; climate is the long-run average of a place.', 12),
  (4, 'People on the move: population, migration, cities', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe where people live, why they migrate, and why the world is urbanizing. Warm-up: roughly what share of humanity now lives in cities?"},{"heading":"The idea","text":"People are spread very unevenly: over half of humanity lives in Asia, with India and China each holding well over a billion people, while deserts, high mountains, and polar zones stay nearly empty. *Population density* measures people per unit of land. When people move, geographers weigh *push factors* (war, poverty, drought, few jobs) against *pull factors* (safety, opportunity, family). *Urbanization* — the shift from countryside to cities — passed a milestone around 2007 when, for the first time, more than half the world lived in urban areas. The very largest cities, called *megacities* (over 10 million people), include Tokyo, Delhi, Shanghai, and São Paulo."},{"heading":"Worked example","text":"A young worker leaves a drought-stricken rural village (a push factor: failing farms) for a coastal megacity offering factory jobs (a pull factor: work). Multiply that decision across millions of people and you get rapid urbanization — cities swelling while some rural regions shrink."},{"heading":"Your turn","text":"Label each as push (P) or pull (L): (1) a civil war forces families to flee, (2) a city offers better schools, (3) repeated crop failures from drought, (4) relatives already living abroad, (5) higher wages in another country, (6) political persecution. Answers: (1) P, (2) L, (3) P, (4) L, (5) L, (6) P."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the biggest country by area has the most people (Russia is largest by land but far from most populous). Mistake: thinking migration is always international — most moves are within a country, from rural to urban. Exit: (a) What do we call a city over 10 million people? (b) Give one push and one pull factor. Answers: a megacity; e.g. war (push) and jobs (pull)."}]}'::jsonb, 'Push factors drive people out; pull factors draw them in.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The Himalayas are still growing because of a…","options":["divergent boundary","convergent (colliding) boundary","transform boundary","hurricane"],"answer":1,"explanation":"The Indian and Eurasian plates collide."},{"prompt":"Most of the world''s major hot deserts lie near…","options":["the equator","30° north and south latitude","the poles","the ocean floor"],"answer":1,"explanation":"Dry sinking air dominates those latitudes."},{"prompt":"The cold, treeless biome near the poles is the…","options":["savanna","taiga","tundra","rainforest"],"answer":2,"explanation":"Tundra is frozen and treeless."},{"prompt":"War and drought that drive people to leave a place are…","options":["pull factors","push factors","megacities","biomes"],"answer":1,"explanation":"They push people out."},{"prompt":"A city with more than 10 million residents is called a…","options":["capital","suburb","megacity","hamlet"],"answer":2,"explanation":"Megacity is the standard term."},{"prompt":"The Ring of Fire is best known for…","options":["deserts","earthquakes and volcanoes","rainforests","glaciers"],"answer":1,"explanation":"It rims the Pacific with tectonic activity."}]}'::jsonb, null, 8),
  (6, 'Culture, language, and belief', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how languages and religions are distributed and how culture spreads across regions. Warm-up: which single language family is spoken natively across both Europe and South Asia?"},{"heading":"The idea","text":"*Culture* is the shared way of life — language, religion, food, customs — passed between people. Languages sort into *language families*: Indo-European (from Europe through Iran to northern India), Sino-Tibetan (including Mandarin Chinese), Niger-Congo across much of sub-Saharan Africa, Afro-Asiatic (including Arabic), and Austronesian across island Southeast Asia and the Pacific. The largest world religions — Christianity, Islam, Hinduism, and Buddhism — began in particular *cultural hearths* and then spread by trade, migration, and conquest, a process geographers call *diffusion*. Hinduism concentrates in South Asia; Islam stretches from North Africa to Indonesia; Christianity is widespread across the Americas, Europe, and much of Africa."},{"heading":"Worked example","text":"Buddhism began in South Asia but diffused along trade routes into East and Southeast Asia, where it is now widespread — an example of a religion spreading far from its hearth. Meanwhile Arabic, an Afro-Asiatic language, spread with Islam across North Africa and Southwest Asia, so today the two often overlap on the map."},{"heading":"Your turn","text":"Match each to its family or region: (1) Mandarin Chinese, (2) Arabic, (3) most languages of sub-Saharan Africa, (4) English and Hindi share this family, (5) the religion concentrated in South Asia. Options: Indo-European / Sino-Tibetan / Afro-Asiatic / Niger-Congo / Hinduism. Answers: (1) Sino-Tibetan, (2) Afro-Asiatic, (3) Niger-Congo, (4) Indo-European, (5) Hinduism."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming a country has just one language or religion — most are diverse. Mistake: thinking a religion stays where it began (diffusion spreads it widely). Exit: (a) What is the birthplace of a cultural idea called? (b) Name the process by which culture spreads. Answers: a cultural hearth; diffusion."}]}'::jsonb, 'A cultural hearth is a birthplace of ideas; diffusion is how they spread.', 12),
  (7, 'Wealth, work, and development', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compare how geographers measure development and explain the idea of sustainable growth. Warm-up: what does HDI add that plain income (GDP) leaves out?"},{"heading":"The idea","text":"Economies are often split into sectors: the *primary* sector takes raw materials from the earth (farming, mining), the *secondary* sector makes goods (manufacturing), and the *tertiary* sector provides services (banking, tourism, health care). To compare countries, geographers use *GDP* (total economic output) but also the *Human Development Index (HDI)*, which blends income with education and life expectancy — so a place can be richer in one measure yet lag in another. Wealth is unevenly spread, often described as a *core* of high-income regions and a *periphery* of lower-income ones. *Sustainable development* asks how societies can raise living standards while protecting the environment for future generations."},{"heading":"Worked example","text":"A country might have modest GDP per person yet score respectably on HDI because it invests heavily in schools and health care, giving long life expectancy and high literacy. That gap is exactly why geographers look beyond income alone when they rank development."},{"heading":"Your turn","text":"Classify each job by sector: (1) wheat farming, (2) assembling cars in a factory, (3) working at a bank, (4) copper mining, (5) teaching in a school, (6) running a tourist hotel. Answers: (1) primary, (2) secondary, (3) tertiary, (4) primary, (5) tertiary, (6) tertiary."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating GDP as the whole story — it ignores health and education. Mistake: assuming ''development'' means unlimited growth regardless of the environment. Exit: (a) Which index blends income, schooling, and life expectancy? (b) Which sector covers services? Answers: HDI; tertiary."}]}'::jsonb, 'Primary = raw materials; secondary = manufacturing; tertiary = services.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"plate tectonics","translation":"the theory that Earth''s outer shell is broken into moving plates that shape landforms","example":"Plate tectonics explains why the Himalayas keep rising."},{"term":"biome","translation":"a large community of plants and animals shaped by a region''s climate","example":"The tropical rainforest is the wettest, most diverse biome."},{"term":"urbanization","translation":"the growing share of people living in cities rather than the countryside","example":"Rapid urbanization has produced dozens of megacities in Asia."},{"term":"push and pull factors","translation":"conditions that drive people away from a place (push) or draw them toward one (pull)","example":"Drought is a push factor; better jobs are a pull factor."},{"term":"cultural diffusion","translation":"the spread of ideas, language, or religion from one place to others","example":"Buddhism reached East Asia through cultural diffusion along trade routes."},{"term":"Human Development Index (HDI)","translation":"a measure combining income, education, and life expectancy to compare development","example":"HDI can rank a country higher than its income alone would suggest."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"English and Hindi both belong to which language family?","options":["Sino-Tibetan","Indo-European","Niger-Congo","Austronesian"],"answer":1,"explanation":"Indo-European spans Europe to South Asia."},{"prompt":"The birthplace of a cultural idea or religion is called a…","options":["periphery","cultural hearth","biome","megacity"],"answer":1,"explanation":"Ideas then diffuse outward from the hearth."},{"prompt":"Manufacturing cars belongs to which economic sector?","options":["primary","secondary","tertiary","none"],"answer":1,"explanation":"Secondary means making goods."},{"prompt":"Which measure blends income, education, and life expectancy?","options":["GDP","latitude","HDI","birth rate"],"answer":2,"explanation":"The Human Development Index."},{"prompt":"Raising living standards while protecting the environment for the future is…","options":["urbanization","diffusion","sustainable development","erosion"],"answer":2,"explanation":"That is the core idea of sustainability."},{"prompt":"Hinduism is concentrated mainly in…","options":["South America","South Asia","Northern Europe","Australia"],"answer":1,"explanation":"It is centered in South Asia, especially India and Nepal."}]}'::jsonb, null, 8),
  (10, 'Applied project: profile a country''s geography', 'writing', '{"sections":[{"heading":"The task","text":"Choose any country you find interesting and write a short geographic profile of it, then describe one real challenge it faces. Pull together the whole course: physical setting, people, culture, and economy."},{"heading":"Milestones","text":"1) Physical geography: describe its landforms and climate/biomes (e.g. mountains, coastline, desert, rainforest). 2) Human geography: where do most people live, and is it urbanizing or migrating? 3) Culture: note a major language and religion. 4) Economy: name a leading sector and one development measure (GDP or HDI). 5) The challenge: pick one real issue — for example water scarcity, rapid urban growth, natural-hazard risk, or balancing growth with sustainability — and explain how the country''s geography shapes it."},{"heading":"Self-check rubric","text":"✔ You covered physical setting, population, culture, and economy — not just one. ✔ Your facts are geographically accurate and specific to that country. ✔ The challenge you chose is genuinely tied to the country''s geography, not generic. ✔ You explained cause and effect, not just listed facts. If all four are true, you''ve analyzed a place like a geographer."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000015' and l.position = v.pos
);
